// Font bytes for the share-card function. Generated from ./fonts/*.ttf.

function decode(b64: string) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export const cormorantRegular = decode("");

export const cormorantItalic = decode("");

export const outfitMedium = decode("");
